import java.io.*;

public class CheckedExample {
  public static void main(String[] args) {
    try (BufferedReader r = new BufferedReader(new FileReader("config.txt"))) {
      String line = r.readLine();
      System.out.println("Config: " + line);
    } catch (IOException e) {
      System.err.println("File IO failed: " + e.getMessage());
      // Caller MUST handle or declare — compiler enforces this
    }
  }
}
